def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    MOD = 1_000_000_007
    if n == 0:
        return 1
    if not banned:
        return pow(len(alphabet), n, MOD)

    size = len(alphabet)
    char_id = {ch: i for i, ch in enumerate(alphabet)}
    transitions = [[-1] * size]
    failure = [0]
    terminal = [False]

    for word in banned:
        state = 0
        for ch in word:
            c = char_id[ch]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * size)
                failure.append(0)
                terminal.append(False)
            state = transitions[state][c]
        terminal[state] = True

    queue = deque()
    for c in range(size):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[failure[state]]
        for c in range(size):
            child = transitions[state][c]
            if child == -1:
                transitions[state][c] = transitions[failure[state]][c]
            else:
                failure[child] = transitions[failure[state]][c]
                queue.append(child)

    safe_states = [s for s in range(len(transitions)) if not terminal[s]]
    index = {s: i for i, s in enumerate(safe_states)}
    count = len(safe_states)
    matrix = [[0] * count for _ in range(count)]

    for state in safe_states:
        row = matrix[index[state]]
        for target in transitions[state]:
            if not terminal[target]:
                row[index[target]] += 1

    def multiply(a, b):
        result = [[0] * count for _ in range(count)]
        for i, a_row in enumerate(a):
            result_row = result[i]
            for k, value in enumerate(a_row):
                if value:
                    for j, other in enumerate(b[k]):
                        result_row[j] += value * other
            for j in range(count):
                result_row[j] %= MOD
        return result

    vector = [0] * count
    vector[index[0]] = 1

    while n:
        if n & 1:
            next_vector = [0] * count
            for i, value in enumerate(vector):
                if value:
                    for j, weight in enumerate(matrix[i]):
                        next_vector[j] += value * weight
            vector = [value % MOD for value in next_vector]

        n >>= 1
        if n:
            matrix = multiply(matrix, matrix)

    return sum(vector) % MOD
